describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the first bracket where weight <= upToGrams (sorted)", () => {
      // 400g: should match the 500g bracket (costCents: 300)
      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    });

    it("uses exact boundary of bracket", () => {
      // 500g exactly: matches 500g bracket
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("bumps to next bracket at boundary + 1", () => {
      // 501g: should match the 1000g bracket (costCents: 500)
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g: matches 2000g bracket
      expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g: overflow
      expect(calc.computeShippingCents([makeLine("a", 2001, 1)], 1000)).toBe(1200);
    });

    it("falls back to heaviest bracket cost when no overflowCostCents", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // 1500g exceeds all brackets, no overflow → uses last bracket cost (500)
      expect(noOverflow.computeShippingCents([makeLine("a", 1500, 1)], 1000)).toBe(500);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 lines: 300g * 2 = 600g, 200g * 1 = 200g, total = 800g → 1000g bracket
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for product not in cart", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product({ id: "p2", name: "Gadget" }), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect internal state", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1500);
    });

    it("applies discount policy and clamps to [0, subtotal]", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(200);
      expect(totals.subtotalCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps discount exceeding subtotal to subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("computes tax on discounted subtotal", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      cart.totals();
      // tax should be computed on discounted subtotal: 1000 - 200 = 800
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    });

    it("uses configured region for tax", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax, region: "FR" });
      cart.add(product(), 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
    });

    it("computes shipping with lines and discounted subtotal", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        900, // discounted subtotal
      );
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const totals = cart.totals();
      // discountedSubtotal = 1000 - 100 = 900
      // total = 900 + 72 + 599 = 1571
      expect(totals.totalCents).toBe(1571);
    });

    it("empty cart has zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(product(), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(product(), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });
});

