describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("uses refreshed prices in totals", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1", unitPriceCents: 1000 }), 2);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      // refreshed subtotal: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("inventory check", () => {
    it("passes when available is true", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(1000);
    });

    it("throws InventoryError when available is false", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1" }), 3);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 1,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(1);
        expect(err.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available=true but qty < requested)", async () => {
      const cart = new Cart();
      cart.add(product({ id: "p1" }), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("checks each line and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product({ id: "a" }), 1);
      cart.add(product({ id: "b" }), 1);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
        InventoryError,
      );
      expect(checker.check).toHaveBeenCalledTimes(2);
    });
  });

  describe("async tax provider", () => {
    it("uses async tax rate in totals computation", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // tax: 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product(), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 200 },
      });
      cart.add(product({ unitPriceCents: 1000 }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // discounted: 1000 - 200 = 800, tax: 10% of 800 = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.discountCents).toBe(200);
    });
  });

  describe("full pipeline", () => {
    it("combines price refresh + inventory + async tax + shipping", async () => {
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 500 },
        shippingCalculator: {
          computeShippingCents: () => 399,
        },
        region: "US-CA",
      });
      cart.add(product({ id: "p1", unitPriceCents: 1000 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 500 (clamped to [0, 2400])
      expect(result.totals.discountCents).toBe(500);
      // discounted subtotal: 2400 - 500 = 1900
      // tax: 8.75% of 1900 = 166.25 → 166
      expect(result.totals.taxCents).toBe(166);
      // shipping: 399
      expect(result.totals.shippingCents).toBe(399);
      // total: 1900 + 166 + 399 = 2465
      expect(result.totals.totalCents).toBe(2465);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("works with no collaborators (all optional)", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0],
    [100],
    [999999],
    [-50],
  ])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %s (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down fractional cents (15% of 999 = 149.85 → 149)", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns full amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies using original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed = 200, sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (clamping is caller responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each capped at subtotal 1000 individually, sum = 2000
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // first: 10% of 1000 = 100, remaining 900
      // second: 10% of 900 = 90, remaining 810
      // total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // first: min(600, 1000) = 600, remaining 400
      // second: min(600, 400) = 400, remaining 0
      // total discount = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("order matters - larger discount first yields different result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const subtotal = 1000;
      // composite1: 50% of 1000=500 remaining 500, then min(100,500)=100, total=600
      // composite2: min(100,1000)=100 remaining 900, then 50% of 900=450, total=550
      expect(composite1.computeDiscountCents(subtotal)).toBe(600);
      expect(composite2.computeDiscountCents(subtotal)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when mode is not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

