      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 500 },
        shippingCalculator: {
          computeShippingCents: () => 399,
        },
        region: "US-CA",
      });
      cart.add(product({ id: "p1", unitPriceCents: 1000 }), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider,
      });

      // subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 500 (clamped to [0, 2400])
      expect(result.totals.discountCents).toBe(500);
      // discounted subtotal: 2400 - 500 = 1900
      // tax: 8.75% of 1900 = 166.25 → 166
      expect(result.totals.taxCents).toBe(166);
      // shipping: 399
      expect(result.totals.shippingCents).toBe(399);
      // total: 1900 + 166 + 399 = 2465
      expect(result.totals.totalCents).toBe(2465);

      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("works with no collaborators (all optional)", async () => {
      const cart = new Cart();
      cart.add(product({ unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });
