import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (overrides: Partial<Product> = {}): Product => ({
  id: "p1",
  name: "Widget",
  unitPriceCents: 1000,
  ...overrides,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(product(), 2);
      cart.add(product(), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 0)).toThrow(RangeError);
      expect(() => cart.add(product(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product(), 3);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

